from typing import List
import math


def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)


def maxLength(nums: List[int]) -> int:
    n = len(nums)
    max_length = 0

    for start in range(n):
        current_gcd = nums[start]
        current_lcm = nums[start]
        current_product = nums[start]

        for end in range(start, n):
            if end > start:
                current_product *= nums[end]
                current_gcd = gcd(current_gcd, nums[end])
                current_lcm = lcm(current_lcm, nums[end])

            if current_product == current_lcm * current_gcd:
                max_length = max(max_length, end - start + 1)

    return max_length

from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse from left to right
            for j in range(0, len(grid[i])):
                if j % 2 == 0:
                    result.append(grid[i][j])
        else:
            # Traverse from right to left
            for j in range(len(grid[i]) - 1, -1, -1):
                if j % 2 != 0:
                    result.append(grid[i][j])
    return result

