def reverseDegree(s: str) -> int:
    reverse_alphabet_value = {chr(i): 26 - (i - 97) for i in range(97, 123)}
    total = 0
    for index, char in enumerate(s, start=1):
        total += reverse_alphabet_value[char] * index
    return total

def calculateScore(s: str) -> int:
    score = 0
    marked = [False] * len(s)
    mirror = {chr(i): chr(219 - i) for i in range(97, 123)}  # a-z to z-a

    for i in range(len(s)):
        if marked[i]:
            continue
        for j in range(i - 1, -1, -1):
            if marked[j]:
                continue
            if mirror[s[i]] == s[j]:
                marked[i] = True
                marked[j] = True
                score += (i - j)
                break
    return score

