def maximumCoins(coins: List[List[int]], k: int) -> int:
    # Create a dictionary to store the coins at each coordinate
    coord_coins = {}

    # Populate the dictionary with coins for each range
    for l, r, c in coins:
        for i in range(l, r + 1):
            if i in coord_coins:
                coord_coins[i] += c
            else:
                coord_coins[i] = c

    # Now we need to find the maximum coins in any k consecutive bags
    max_coins = 0
    current_coins = 0
    active_bags = []

    # Use a sorted list of coordinates
    sorted_coords = sorted(coord_coins.keys())

    left = 0
    for right in range(len(sorted_coords)):
        current_coins += coord_coins[sorted_coords[right]]
        active_bags.append(sorted_coords[right])

        # When we exceed k bags, remove the leftmost
        while len(active_bags) > k:
            current_coins -= coord_coins[active_bags[0]]
            active_bags.pop(0)

        # Update maximum coins collected for valid k bags
        if len(active_bags) == k:
            max_coins = max(max_coins, current_coins)

    return max_coins

